.ds {
  --ds-bg:var(--p-bg,#ffffff);
  --ds-surface:var(--p-surface,#f1f3f6);
  --ds-high:var(--p-high,#fafbfc);
  --ds-text:var(--p-ink,#2c333d);
  --ds-muted:var(--p-muted,#59636f);
  --ds-border:var(--p-line,#c2cad5);
  --ds-control-border:var(--p-control-border,#7b8592);
  --ds-soft:var(--p-soft,#d3e8de);
  --ds-accent:var(--p-accent,#303b48);
  --ds-on-accent:var(--p-on-accent,#ffffff);
  --ds-focus:var(--p-highlight,#6153b5);
  --ds-error:var(--p-error,#a3313e);
  --ds-success:var(--p-success,#26614f);
  --ds-warning:var(--p-warning,#805719);
  --ds-radius:var(--p-radius,24px);
  --ds-control-radius:var(--p-control-radius,16px);
  --ds-shadow:var(--p-shadow,6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed);
  --ds-raised:var(--p-raised,3px 4px 8px #b9c3d066, -3px -3px 8px #ffffffed);
  --ds-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9);
  --ds-glass:var(--p-glass,#f6f8fbe8);
  --ds-disabled:var(--p-disabled,#dce1e8);
  --ds-duration:var(--p-duration,140ms);
  --ds-font:var(--p-font,Pretendard, sans-serif);
  --ds-display-font:var(--p-display-font,Outfit, Pretendard, sans-serif);
  --ds-text-sm:var(--p-text-sm,13px);
  --ds-text-md:var(--p-text-md,16px);
  --ds-text-lg:var(--p-text-lg,24px);
  --ds-space-2:var(--p-space-xs,8px);
  --ds-space-3:var(--p-space-sm,12px);
  --ds-space-4:var(--p-space-md,16px);
  --ds-space-6:var(--p-space-lg,24px);
  --ds-space-8:var(--p-space-xl,32px);
}
.ds {
  color:var(--ds-text); background:var(--ds-bg); font:var(--ds-text-md)/1.5 var(--ds-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--ds-focus); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--ds-text-sm); margin-top:var(--ds-space-3); min-height:20px; color:var(--ds-muted); }
.ds .ds-surface { border:1px solid var(--ds-border); border-radius:var(--ds-radius); background:var(--ds-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--ds-shadow); border-color:#ffffff; }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--ds-inset); background:var(--ds-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--ds-high); box-shadow:0 8px 24px #38465e12; }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--ds-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--ds-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds .ds-feedback-example { display:grid; gap:var(--ds-space-4); }
.ds .ds-feedback-example > .ds-button { justify-self:start; }
.ds .ds-alert { padding:var(--ds-space-4); border:1px solid var(--ds-success); border-radius:var(--ds-control-radius); background:var(--ds-high); box-shadow:var(--ds-raised); }
.ds .ds-progress-label { display:flex; justify-content:space-between; gap:var(--ds-space-2); font-size:var(--ds-text-sm); }
.ds .ds-progress { display:block; appearance:none; width:100%; height:12px; border:1px solid var(--ds-control-border); border-radius:8px; background:var(--ds-bg); color:var(--ds-success); box-shadow:var(--ds-inset); overflow:hidden; }
.ds .ds-progress::-webkit-progress-bar { background:var(--ds-bg); border-radius:8px; box-shadow:var(--ds-inset); }
.ds .ds-progress::-webkit-progress-value { background:var(--ds-success); border-radius:8px; }
.ds .ds-progress::-moz-progress-bar { background:var(--ds-success); border-radius:8px; }
/* Looks: the notice and the bar keep their roles; the saved notice always carries its dot and words, the bar always its number. */
.ds .ds-feedback-example[data-look] .ds-alert { justify-self:stretch; }
/* toast: the notice carries its own undo, so no confirm step is needed */
.ds .ds-feedback-example[data-look="toast"] .ds-alert { border-color:var(--ds-accent); border-radius:14px; background:var(--ds-accent); color:var(--ds-on-accent); box-shadow:var(--ds-shadow); }
/* 06 ring: the number sits inside a round gauge; the real progress element stays for screen readers */
.ds .ds-feedback-example[data-look="ring"] { grid-template-columns:auto minmax(0,1fr); align-items:center; column-gap:var(--ds-space-4); }
.ds .ds-feedback-example[data-look="ring"] > :is(.ds-button,.ds-alert) { grid-column:1/-1; }
.ds .ds-progress-ring { position:relative; display:grid; place-items:center; width:72px; aspect-ratio:1; }
.ds .ds-progress-ring::before { content:''; position:absolute; inset:0; border-radius:50%; background:conic-gradient(var(--ds-success) calc(var(--value) * 1%), var(--ds-border) 0); -webkit-mask:radial-gradient(farthest-side, transparent calc(100% - 9px), black calc(100% - 8px)); mask:radial-gradient(farthest-side, transparent calc(100% - 9px), black calc(100% - 8px)); }
.ds .ds-progress-ring b { font:700 16px/1 var(--ds-display-font); letter-spacing:-.02em; }
.ds .ds-feedback-example[data-look="ring"] .ds-progress-label { font-size:14px; font-weight:600; }
.ds .ds-feedback-example[data-look="ring"] :is(.ds-progress-label > :last-child,.ds-progress) { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
/* 08 steps: the bar is cut into ten blocks, so progress reads as a count */
.ds .ds-feedback-example[data-look="steps"] .ds-alert { border:0; border-radius:12px; background:var(--ds-soft); box-shadow:none; }
.ds .ds-feedback-example[data-look="steps"] .ds-progress { height:14px; border:0; border-radius:0; background:var(--ds-border); box-shadow:none; -webkit-mask:repeating-linear-gradient(90deg, black 0 calc(10% - 4px), transparent 0 10%); mask:repeating-linear-gradient(90deg, black 0 calc(10% - 4px), transparent 0 10%); }
.ds .ds-feedback-example[data-look="steps"] .ds-progress::-webkit-progress-bar { background:var(--ds-border); border-radius:0; box-shadow:none; }
.ds .ds-feedback-example[data-look="steps"] .ds-progress::-webkit-progress-value { border-radius:0; }
.ds .ds-feedback-example[data-look="steps"] .ds-progress::-moz-progress-bar { border-radius:0; }
.ds .ds-feedback-example[data-look="toast"] .ds-alert { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:var(--ds-space-2); padding-block:6px; }
.ds .ds-feedback-example[data-look="toast"] .ds-status i { background:var(--ds-on-accent); }
.ds .ds-alert-undo { min-height:44px; padding:0 12px; border:0; border-radius:10px; background:transparent; color:inherit; font:inherit; font-size:14px; font-weight:700; text-decoration:underline; text-underline-offset:3px; cursor:pointer; }
.ds .ds-alert-undo:hover { background:color-mix(in oklab, currentColor 14%, transparent); }
.ds .ds-alert-undo:focus-visible { outline-color:currentColor; outline-offset:-3px; }

.ds .ds-button { display:inline-flex; justify-content:center; align-items:center; gap:var(--ds-space-2); min-width:48px; min-height:48px; padding:10px 20px; border:1px solid var(--ds-accent); border-radius:var(--ds-control-radius); background:var(--ds-accent); color:var(--ds-on-accent); font-size:14px; font-weight:650; line-height:1.4; box-shadow:0 3px 5px #24314526,inset 0 1px 0 #ffffff24; text-decoration:none; transition:background var(--ds-duration),box-shadow var(--ds-duration); }
.ds .ds-button[data-variant="outline"] { border-color:var(--ds-control-border); color:var(--ds-text); background:var(--ds-surface); box-shadow:var(--ds-raised); }
.ds .ds-button[data-variant="ghost"] { color:var(--ds-text); background:transparent; border-color:transparent; box-shadow:none; }
.ds .ds-button[data-size="sm"] { min-height:44px; min-width:44px; padding:8px 16px; font-size:13px; }
.ds .ds-button[data-size="lg"] { min-height:56px; min-width:56px; padding:14px 24px; font-size:16px; }
.ds .ds-button[data-icon-only] { padding:10px; }
.ds .ds-button:not(:disabled):is(:hover,[data-state="hover"]) { background:color-mix(in srgb,var(--ds-accent) 84%,#000); }
.ds .ds-button[data-variant="outline"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--ds-high); }
.ds .ds-button[data-variant="ghost"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--ds-disabled); }
.ds .ds-button:not(:disabled):is(:active,[data-state="pressed"]) { box-shadow:inset 3px 3px 6px #15222f60,inset -1px -1px 3px #ffffff18; }
.ds .ds-button:not([data-variant="primary"]):not(:disabled):is(:active,[data-state="pressed"]) { background:var(--ds-bg); box-shadow:var(--ds-inset); }
.ds .ds-button[data-state="focus"] { outline:3px solid var(--ds-focus); outline-offset:3px; }
.ds .ds-button:disabled { opacity:1; box-shadow:none; background:var(--ds-disabled); border-color:var(--ds-border); color:var(--ds-muted); }
.ds .ds-button[aria-busy="true"] { background:var(--ds-accent); color:var(--ds-on-accent); border-color:var(--ds-accent); }
.ds .ds-spinner { width:16px; height:16px; flex-shrink:0; border:2px solid currentColor; border-right-color:transparent; border-radius:50%; animation:ds-spin .8s linear infinite; }
@keyframes ds-spin { to { transform:rotate(360deg); } }
@media(prefers-reduced-motion:reduce) { .ds .ds-spinner { border-style:dotted; } }
/* looks: primary colors change per look, pill/cta change shape for every variant; disabled keeps the base state */
/* looks: arrangements of actions; colour roles stay on data-variant */
.ds .ds-actions { display:flex; flex-wrap:wrap; align-items:center; gap:var(--ds-space-2); min-width:0; }
.ds .ds-button-count { display:inline-grid; place-items:center; min-width:22px; height:22px; padding:0 6px; border-radius:99px; background:var(--ds-accent); color:var(--ds-on-accent); font-size:12px; font-weight:700; line-height:1; }
.ds .ds-button[data-variant="primary"] .ds-button-count { background:var(--ds-on-accent); color:var(--ds-accent); }
.ds .ds-actions[data-look="hero"] { flex-wrap:nowrap; gap:0; }
.ds .ds-actions[data-look="hero"] > .ds-button:first-child { flex:1 0 auto; margin-right:var(--ds-space-2); padding-inline:16px; white-space:nowrap; }
.ds .ds-actions[data-look="hero"] > .ds-button[data-icon-only] { flex:none; width:44px; min-width:44px; padding:0; }
.ds .ds-actions[data-look="hero"] > .ds-button[data-icon-only] { color:var(--ds-text); }
.ds .ds-actions[data-look="pair"] { justify-content:flex-end; }
.ds .ds-actions[data-look="pair"] > .ds-button { flex:0 1 auto; }
.ds .ds-actions[data-look="bar"] { width:100%; padding:var(--ds-space-3); border-top:1px solid var(--ds-border); background:var(--ds-bg); }
.ds .ds-actions[data-look="bar"] > .ds-button { flex:1; min-height:52px; }

.ds .ds-status { display:inline-flex; gap:var(--ds-space-2); align-items:center; font-size:var(--ds-text-sm); }
.ds .ds-status i { width:8px; height:8px; flex-shrink:0; border-radius:50%; background:var(--ds-success); }
.ds .ds-status[data-look="avatar"] { position:relative; gap:var(--ds-space-3); }
.ds .ds-status[data-look="avatar"]::before { content:''; width:36px; height:36px; flex-shrink:0; border-radius:50%; background:var(--ds-soft); }
.ds .ds-status[data-look="avatar"] i { position:absolute; left:25px; top:calc(50% + 6px); width:12px; height:12px; box-shadow:0 0 0 2px var(--ds-bg); }
.ds .ds-status[data-look="check"] i { position:relative; width:18px; height:18px; }
.ds .ds-status[data-look="check"] i::after { content:''; position:absolute; left:6px; top:3px; width:4px; height:8px; border:solid var(--ds-on-accent); border-width:0 2px 2px 0; transform:rotate(45deg); }

'use client';
import React, { useState } from 'react';
import { Button } from './button.jsx';
import { StatusDot } from './status-dot.jsx';
// look matches the HTML data-look values; the ring look draws the progress as a circle beside the same progress bar,
// and the toast look carries an undo so the save runs at once instead of asking first.
export function Feedback({ progress = 68, onSave, onUndo, look = 'card' }) {
  const [status, setStatus] = useState(''); const [loading, setLoading] = useState(false); const [saved, setSaved] = useState(false);
  const value = Math.min(100, Math.max(0, Number(progress) || 0));
  async function save() { setLoading(true); setStatus(''); setSaved(false); try { await onSave?.(); setStatus('변경사항을 저장했어요.'); setSaved(true); } catch { setStatus('저장하지 못했어요. 다시 시도해 주세요.'); } finally { setLoading(false); } }
  function undo() { setStatus(''); setSaved(false); onUndo?.(); }
  return <div className="ds-feedback-example" data-look={look}><Button loading={loading} onClick={save}>저장</Button><div role="status">{status && <div className="ds-alert"><StatusDot>{status}</StatusDot>{look === 'toast' && saved && <button type="button" className="ds-alert-undo" onClick={undo}>되돌리기</button>}</div>}</div>{look === 'ring' && <span className="ds-progress-ring" aria-hidden="true" style={{ '--value': value }}><b>{value}%</b></span>}<div className="ds-progress-label"><span>파일 업로드</span><span>{value}%</span></div><progress className="ds-progress" value={value} max="100" aria-label="파일 업로드">{value}%</progress></div>;
}

import React from 'react';
// count joins the accessible name ("보내기 3개") and shows as a small number next to the label.
export function Button({ children, look, count, variant = 'primary', size = 'md', loading = false, disabled, className = '', type = 'button', ...props }) {
  const named = count != null && typeof children === 'string' ? `${children} ${count}개` : undefined;
  return <button {...props} type={type} className={`ds-button ${className}`} data-variant={variant} data-size={size} data-look={look} disabled={disabled || loading} aria-busy={loading || undefined} aria-label={props['aria-label'] ?? named}>
    {loading && <span className="ds-spinner" aria-hidden="true" />}{children}{count != null && <span className="ds-button-count" aria-hidden="true">{count}</span>}
  </button>;
}
// The hero, pair and bar looks are arrangements of several buttons: wrap them in Actions with that look.
export function Actions({ look = 'hero', children, ...props }) { return <div {...props} className="ds-actions" data-look={look}>{children}</div>; }

'use client';
